const $=s=>document.querySelector(s),KEY='course-flow-v1',days=['周一','周二','周三','周四','周五','周六','周日'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('sv-SE');
let state={courses:[],tasks:[]},view='overview',filter='all';
function validate(s){if(!s||!Array.isArray(s.courses)||!Array.isArray(s.tasks))throw Error('备份格式不正确');const ids=new Set();for(const c of s.courses){if(typeof c.id!=='string'||ids.has(c.id)||typeof c.name!=='string'||!c.name.trim()||typeof c.room!=='string'||!Number.isInteger(c.day)||c.day<0||c.day>6||!/^([01]\d|2[0-3]):[0-5]\d$/.test(c.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(c.end)||c.start>=c.end||!Number.isInteger(c.total)||c.total<1||!Number.isInteger(c.done)||c.done<0||c.done>c.total)throw Error('课程数据无效');ids.add(c.id)}const taskIds=new Set();for(const t of s.tasks){if(typeof t.id!=='string'||taskIds.has(t.id)||typeof t.title!=='string'||!t.title.trim()||!ids.has(t.course)||!/^\d{4}-\d{2}-\d{2}$/.test(t.due)||Number.isNaN(Date.parse(t.due))||typeof t.done!=='boolean')throw Error('作业数据无效');taskIds.add(t.id)}return s}
try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved))}catch(e){$('#notice').textContent='读取本地数据失败，请导入有效备份。'}
function commit(next){try{validate(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;render();return true}catch(e){$('#notice').textContent='保存失败：'+e.message;return false}}
function mutate(fn){const next=structuredClone(state);fn(next);return commit(next)}
function courseName(id){return state.courses.find(c=>c.id===id)?.name||''}
function taskRows(tasks){return tasks.length?tasks.map(t=>`<div class="row"><input aria-label="完成 ${esc(t.title)}" type="checkbox" data-check="${esc(t.id)}" ${t.done?'checked':''}><div class="grow"><b>${esc(t.title)}</b><small>${esc(courseName(t.course))} · ${esc(t.due)}</small></div><span class="badge ${!t.done&&t.due<today()?'danger':''}">${t.done?'已完成':t.due<today()?'已逾期':'待完成'}</span><button data-edit-task="${esc(t.id)}" aria-label="编辑作业">编辑</button><button data-delete-task="${esc(t.id)}" aria-label="删除作业">×</button></div>`).join(''):'<p class="empty">暂时没有作业，给学习留一点从容。</p>'}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#title').textContent=({overview:'学习概览',schedule:'我的课表',tasks:'作业清单',courses:'学习进度'})[view];$('#add').textContent=view==='tasks'?'＋ 添加作业':'＋ 添加课程';const pending=state.tasks.filter(t=>!t.done).sort((a,b)=>a.due.localeCompare(b.due));const total=state.courses.reduce((n,c)=>n+c.total,0),done=state.courses.reduce((n,c)=>n+c.done,0);const pct=total?Math.round(done/total*100):0;
if(view==='overview')$('#content').innerHTML=`<div class="stats"><div class="stat">在学课程<strong>${state.courses.length}<span> 门</span></strong><span>让学习保持节奏</span></div><div class="stat">待完成作业<strong>${pending.length}<span> 项</span></strong><span>${pending.filter(t=>t.due<today()).length} 项已逾期</span></div><div class="stat">整体学习进度<strong>${pct}<span> %</span></strong><span>已完成 ${done} / ${total} 课时</span></div></div><div class="banner"><span class="badge">每天前进一点</span><h2 style="margin-top:15px">有计划的学习，<br>从容一点，也更进一步。</h2><p>把课程与任务放在一起，让下一步清晰可见。</p></div><div class="grid"><section class="panel"><h2>接下来的作业</h2>${taskRows(pending.slice(0,5))}</section><section class="panel"><h2>今日课程</h2>${state.courses.filter(c=>c.day===(new Date().getDay()+6)%7).sort((a,b)=>a.start.localeCompare(b.start)).map(c=>`<div class="row"><span class="badge">${esc(c.start)}</span><div><b>${esc(c.name)}</b><small>${esc(c.room)||'地点待定'} · 至 ${esc(c.end)}</small></div></div>`).join('')||'<p class="empty">今天没有安排课程。</p>'}</section></div>`;
if(view==='schedule')$('#content').innerHTML=`<p>每周重复课表 · 点击课程可编辑时间和地点</p><div class="scroll"><div class="week">${days.map((day,i)=>`<section class="day"><b>${day}</b>${state.courses.filter(c=>c.day===i).sort((a,b)=>a.start.localeCompare(b.start)).map(c=>`<button class="lesson" data-edit-course="${esc(c.id)}">${esc(c.start)}–${esc(c.end)}<br><b>${esc(c.name)}</b><small>${esc(c.room)||'地点待定'}</small></button>`).join('')}</section>`).join('')}</div></div>`;
if(view==='tasks')$('#content').innerHTML=`<div class="toolbar">${[['all','全部'],['pending','待完成'],['done','已完成']].map(([v,n])=>`<button data-filter="${v}" class="${filter===v?'primary':''}">${n}</button>`).join('')}</div><section class="panel">${taskRows(state.tasks.filter(t=>filter==='all'||t.done===(filter==='done')).sort((a,b)=>a.due.localeCompare(b.due)))}</section>`;
if(view==='courses')$('#content').innerHTML=`<div class="course-grid">${state.courses.map(c=>`<section class="course"><span class="badge">${days[c.day]} · ${esc(c.start)}</span><h2 style="margin-top:16px">${esc(c.name)}</h2><p>${esc(c.room)||'地点待定'}</p><div class="row"><span class="grow">学习进度</span><b>${c.done} / ${c.total} 课时</b></div><progress value="${c.done}" max="${c.total}"></progress><br><button data-progress="${esc(c.id)}" ${c.done===c.total?'disabled':''}>＋ 完成一课时</button><button data-edit-course="${esc(c.id)}">编辑</button><button class="danger" data-delete-course="${esc(c.id)}">删除</button></section>`).join('')||'<section class="panel"><h2>开始你的第一门课程</h2><p>点击右上角添加课程，设置时间与学习目标。</p></section>'}</div>`;
}
function input(label,name,type,value,extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function openForm(kind,id){if(kind==='task'&&!state.courses.length){$('#notice').textContent='请先添加一门课程，再创建作业。';return}const item=(kind==='course'?state.courses:state.tasks).find(x=>x.id===id);$('#formTitle').textContent=(item?'编辑':'添加')+(kind==='course'?'课程':'作业');$('#error').textContent='';$('#fields').innerHTML=kind==='course'?input('课程名称','name','text',item?.name||'','required maxlength="80"')+input('上课地点','room','text',item?.room||'','maxlength="80"')+`<label>上课日<select name="day">${days.map((d,i)=>`<option value="${i}" ${item?.day===i?'selected':''}>${d}</option>`).join('')}</select></label><div class="split">`+input('开始时间','start','time',item?.start||'08:00','required')+input('结束时间','end','time',item?.end||'09:40','required')+'</div><div class="split">'+input('总课时','total','number',item?.total||32,'required min="1" max="10000" step="1"')+input('已完成课时','done','number',item?.done||0,'required min="0" step="1"')+'</div>':input('作业名称','title','text',item?.title||'','required maxlength="150"')+`<label>所属课程<select name="course">${state.courses.map(c=>`<option value="${esc(c.id)}" ${item?.course===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`+input('截止日期','due','date',item?.due||today(),'required');$('#form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const record=kind==='course'?{...data,id:item?.id||crypto.randomUUID(),day:+data.day,total:+data.total,done:+data.done,name:data.name.trim()}:{...data,id:item?.id||crypto.randomUUID(),title:data.title.trim(),done:item?.done||false};if(kind==='course'&&(record.start>=record.end||record.done>record.total)){ $('#error').textContent='结束时间需晚于开始时间，已完成课时不能超过总课时。';return}const next=structuredClone(state),list=kind==='course'?next.courses:next.tasks;if(item)list[list.findIndex(x=>x.id===id)]=record;else list.push(record);try{validate(next)}catch(e){$('#error').textContent=e.message;return}if(commit(next))$('#dialog').close()};$('#dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view){view=d.view;render()}if(d.filter){filter=d.filter;render()}if(d.editCourse)openForm('course',d.editCourse);if(d.editTask)openForm('task',d.editTask);if(d.deleteCourse&&confirm('删除课程及其关联作业？'))mutate(s=>{s.courses=s.courses.filter(c=>c.id!==d.deleteCourse);s.tasks=s.tasks.filter(t=>t.course!==d.deleteCourse)});if(d.deleteTask&&confirm('删除这项作业？'))mutate(s=>s.tasks=s.tasks.filter(t=>t.id!==d.deleteTask));if(d.progress)mutate(s=>{const c=s.courses.find(c=>c.id===d.progress);c.done=Math.min(c.total,c.done+1)})});
document.addEventListener('change',e=>{if(e.target.dataset.check){if(!mutate(s=>s.tasks.find(t=>t.id===e.target.dataset.check).done=e.target.checked))render()}});
$('#add').onclick=()=>openForm(view==='tasks'?'task':'course');$('#close').onclick=()=>$('#dialog').close();$('#date').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`课序备份-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('备份不能超过 2 MB');const data=validate(JSON.parse(await f.text()));if(confirm('导入将替换当前设备的数据，是否继续？')&&commit(data))$('#notice').textContent='备份已导入。'}catch(err){$('#notice').textContent='导入失败：'+err.message}e.target.value=''};
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>$('#notice').textContent='离线缓存暂不可用，仍可在线使用。');
